// swift-tools-version: 5.9
import PackageDescription

// Umbrella plugin: two Capacitor plugins (KmpDevice, KmpMotion) backed by ONE Kotlin framework.
// No dependency on the base plugin's Swift package: its helper (KmpCapacitor.swift) is synced into
// ios/Sources/KmpUmbrellaPlugin/Generated by `npm run kmp:build`.
let package = Package(
    name: "CapacitorKotlinMultiPlatformUmbrella",
    platforms: [.iOS(.v15)],
    products: [
        .library(
            name: "CapacitorKotlinMultiPlatformUmbrella",
            targets: ["KmpUmbrellaPlugin"])
    ],
    dependencies: [
        .package(url: "https://github.com/ionic-team/capacitor-swift-pm.git", from: "8.0.0")
    ],
    targets: [
        // core + device + motion, built by `npm run kmp:build` (kmp/umbrella).
        .binaryTarget(
            name: "KmpUmbrella",
            path: "ios/Frameworks/KmpUmbrella.xcframework"),
        .target(
            name: "KmpUmbrellaPlugin",
            dependencies: [
                .product(name: "Capacitor", package: "capacitor-swift-pm"),
                .product(name: "Cordova", package: "capacitor-swift-pm"),
                "KmpUmbrella"
            ],
            path: "ios/Sources/KmpUmbrellaPlugin"),
        .testTarget(
            name: "KmpUmbrellaPluginTests",
            dependencies: ["KmpUmbrellaPlugin", "KmpUmbrella"],
            path: "ios/Tests/KmpUmbrellaPluginTests")
    ]
)
